// Steigt in die verschachtelten Felder der Einzelrechnung hinab:
// invoice_data, invoice_data.items, invoice_data.counts, items, pay, receipt.
// Zeigt Klarwerte nur bei steuer-, betrags- und kennungsbezogenen Feldern.

const auth = $('S25 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abruf(pfad, qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2${pfad}`,
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abruf.bind(this);

function liste(h) {
  if (!h || typeof h !== 'object') return [];
  const d = h.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

// Rechnungsliste holen und eine gemischte Probe bilden.
const a = await hole('/invoice/list', { 'limit[start]': 0, 'limit[reply]': 2000 });
if (a.statusCode !== 200) throw new Error(`invoice/list Status ${a.statusCode}`);
const roh = liste(a.body).filter((r) => r && r.id);

const proben = [];
for (const s of [1, 2, 3]) {
  for (const r of roh.filter((x) => Number(x.status) === s).slice(0, 3)) proben.push(r);
}
for (const r of roh.slice(-3)) if (!proben.includes(r)) proben.push(r);

const offen = /id$|_id|ref|booking|offer|order|user|trans|vat|ust|tax|steuer|mwst|rate|satz|net|gross|brutto|netto|amount|betrag|total|sum|count|menge|quantity|status|type|art|number|nummer|country|land|currency|contained|included/i;
const geheim = /address|iban|bic|creditor|message|name|mail|street|strasse|phone/i;

function art(w) {
  if (w === null) return 'null';
  if (Array.isArray(w)) return `liste[${w.length}]`;
  if (typeof w === 'object') return `objekt{${Object.keys(w).slice(0, 16).join(',')}}`;
  if (typeof w === 'boolean') return `wahrheitswert:${w}`;
  if (typeof w === 'number') return 'zahl';
  if (typeof w === 'string') {
    if (w === '') return 'text:leer';
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w)) return 'text:zeitpunkt';
    return `text(${w.length})`;
  }
  return typeof w;
}

const uebersicht = new Map();

function erfassen(bereich, obj) {
  if (!obj || typeof obj !== 'object') return;
  for (const [feld, wert] of Object.entries(obj)) {
    const schluessel = bereich + '::' + feld;
    if (!uebersicht.has(schluessel)) {
      uebersicht.set(schluessel, { bereich, feld, arten: new Set(), werte: new Set() });
    }
    const e = uebersicht.get(schluessel);
    e.arten.add(art(wert));
    if (!geheim.test(feld) && offen.test(feld) && (typeof wert !== 'object' || wert === null)) {
      const t = String(wert);
      if (t.length <= 40) e.werte.add(t);
    }
  }
}

let gelesen = 0;
let fehler = '';

for (const p of proben) {
  const antwort = await hole(`/invoice/${encodeURIComponent(String(p.id))}/data`, {});
  if (antwort.statusCode !== 200) {
    if (!fehler) fehler = `Status ${antwort.statusCode}`;
    continue;
  }
  const r0 = antwort.body?.data;
  const r = Array.isArray(r0) ? r0[0] : r0;
  if (!r || typeof r !== 'object') continue;
  gelesen += 1;

  const id = r.invoice_data;
  erfassen('invoice_data', id);

  if (id && typeof id === 'object') {
    const it = id.items;
    if (Array.isArray(it)) {
      erfassen('invoice_data.items[]', it[0]);
      for (const z of it.slice(0, 4)) erfassen('invoice_data.items[]', z);
    } else {
      erfassen('invoice_data.items', it);
      if (it && typeof it === 'object') for (const z of Object.values(it).slice(0, 4)) erfassen('invoice_data.items.wert', z);
    }

    const c = id.counts;
    if (Array.isArray(c)) {
      for (const z of c.slice(0, 4)) erfassen('invoice_data.counts[]', z);
    } else {
      erfassen('invoice_data.counts', c);
      if (c && typeof c === 'object') for (const z of Object.values(c).slice(0, 4)) erfassen('invoice_data.counts.wert', z);
    }

    const dd = id.data;
    erfassen('invoice_data.data', dd);
  }

  erfassen('items', r.items);
  if (r.items && typeof r.items === 'object') {
    const cont = r.items.contained;
    if (Array.isArray(cont)) {
      for (const z of cont.slice(0, 4)) erfassen('items.contained[]', z);
    } else {
      erfassen('items.contained', cont);
      if (cont && typeof cont === 'object') for (const z of Object.values(cont).slice(0, 4)) erfassen('items.contained.wert', z);
    }
  }

  if (r.pay && typeof r.pay === 'object' && !Array.isArray(r.pay)) {
    erfassen('pay', r.pay);
    for (const z of Object.values(r.pay).slice(0, 3)) erfassen('pay.wert', z);
  }

  if (r.receipt && typeof r.receipt === 'object' && !Array.isArray(r.receipt)) {
    erfassen('receipt', r.receipt);
    for (const z of Object.values(r.receipt).slice(0, 3)) erfassen('receipt.wert', z);
  }
}

const zeilen = [{
  json: {
    schritt: 'S25',
    bereich: '(Probe)',
    feld: '',
    arten: `${gelesen} von ${proben.length} Rechnungen gelesen${fehler ? ', Fehler: ' + fehler : ''}`,
    beispielwerte: '',
  },
}];

for (const e of [...uebersicht.values()].sort((x, y) =>
  x.bereich.localeCompare(y.bereich) || x.feld.localeCompare(y.feld))) {
  zeilen.push({
    json: {
      schritt: 'S25',
      bereich: e.bereich,
      feld: e.feld,
      arten: [...e.arten].slice(0, 4).join(' | '),
      beispielwerte: [...e.werte].slice(0, 8).join(' | '),
    },
  });
}

return zeilen;
